67: /** Maps an arcade 0..1 power onto the charge the configured impulse curve expects. */
68: export function chargeForPower(power: number): number {
69:   const config = GAME_CONFIG.physics;
70:   const impulse = powerToSpeed(clamp(power, 0, 1)) * BALL_MASS;
71:   const span = config.maxShotPower - config.minShotPower;
72:   if (span <= 0 || impulse <= config.minShotPower) return 0;
73:   return Math.min(1, Math.pow((impulse - config.minShotPower) / span, 1 / config.powerExponent));
74: }
